D = foot(P,A,-A);

draw(O--P--D);

draw(rightanglemark(O,D,P,2));

draw(Circle(O,1));

label("$O$",O,NW);

label("$P$",P,SE);

//label("$A$",A,SE);

label("$D$",D,N);

[/asy]

